import{_ as a,o,c as r,a2 as s}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Criaturas y anatomía","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/creatures.md","filePath":"es/game-design/creatures.md"}'),n={name:"es/game-design/creatures.md"};function i(t,e,c,d,l,m){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="creatures-and-anatomy" tabindex="-1">Criaturas y anatomía <a class="header-anchor" href="#creatures-and-anatomy" aria-label="Enlace permanente a &quot;Criaturas y anatomía&quot;">​</a></h1><p><strong>Estado del diseño: Aceptado para la dirección de sistemas compartidos; perfiles y conocimiento Sin resolver. Implementación: criaturas existentes, sin perfiles anatómicos de SyroUO.</strong></p><p>PvP y PvM deberían compartir mecánicas cuando corresponda. Las definiciones reutilizables de <code>AnatomyProfile</code> deberían describir regiones de juego independientemente de las categorías corporales de los sprites. Un humanoide, cuadrúpedo o criatura inusual no tiene por qué compartir el mismo mapa de siete regiones.</p><p>El primer entorno de prueba admite únicamente jugadores humanos normales conectados. Las criaturas no compatibles conservan el comportamiento heredado; esta limitación no establece un combate PvM final separado. El conocimiento de criaturas, la fisiología de no muertos/seres no vivos y un posible Bestiary siguen sin resolverse. No inventar lesiones por especie ni importar etiquetas de grupos de animación como anatomía.</p><p><strong>Brecha:</strong> validar el ciclo humano antes de seleccionar perfiles, reglas de divulgación y presentación de recursos gráficos. <a href="/Syrolands-Public/es/game-design/combat/body-regions.html">Regiones corporales</a> · Restricciones del renderizador.</p><h2 id="proposed-environmental-relationships" tabindex="-1">Relaciones ambientales — Propuesto <a class="header-anchor" href="#proposed-environmental-relationships" aria-label="Enlace permanente a &quot;Relaciones ambientales — Propuesto&quot;">​</a></h2><p>La <a href="/Syrolands-Public/es/game-design/living-world.html#ecology-as-a-future-layer">propuesta de ecología del mundo vivo</a> conecta hábitat, recursos y futuras poblaciones o migraciones. Queda fuera del primer prototipo ambiental y no establece nuevos comportamientos de criaturas ni perfiles anatómicos.</p>',7)])])}const g=a(n,[["render",i]]);export{u as __pageData,g as default};
